<script lang="ts">
 import { bytes } from './bridge';
 import type { Job } from './bridge';
 import { testOutcome } from './integrity';
 import type { TestReceipt } from './integrity';
 import EncryptedBadge from './EncryptedBadge.svelte';
 let {name='',files=0,format='',encrypted=false,running=false,job,receipt=null,failure='',passwordRequired=false,onclose,oncancel,onretry,onpassword}:{name?:string;files?:number;format?:string;encrypted?:boolean;running?:boolean;job?:Job;receipt?:TestReceipt|null;failure?:string;passwordRequired?:boolean;onclose:()=>void;oncancel:()=>void;onretry:()=>void;onpassword:()=>void}=$props();
 const result=$derived(testOutcome(receipt,failure,encrypted));
 const state=$derived(running?'running':passwordRequired?'password':result.state);
 const title=$derived(running?(job?.status==='queued'?'Waiting to test…':'Checking archive…'):passwordRequired?'Password required':result.title);
 const fraction=$derived(running?job?.progress??null:state==='passed'?1:null);
 const percent=$derived(fraction===null?null:Math.round(Math.max(0,Math.min(1,fraction))*100));
 const current=$derived(running&&job?.status==='running'&&job.message!=='Starting operation'?job?.message:'');
 const tar=$derived(format.toLowerCase().includes('tar'));
</script>
<section class="test-panel" data-state={state} aria-label="Archive integrity test">
 <div class="archive"><img src="/icons/archive.svg" alt=""/><strong title={name}>{name}</strong></div>
 <div class="result" role="status"><span class="symbol" aria-hidden="true">{state==='running'?'':state==='passed'?'✓':state==='failed'?'×':'−'}</span><div><h3>{title}</h3><p>{running?`${files} ${files===1?'file':'files'} in archive`:state==='passed'?`${files} of ${files} files checked`:state==='password'?'Protected contents have not been checked':result.reason}</p></div></div>
 {#if running||state==='passed'}<div class="work"><progress aria-label="Archive test progress" max="1" value={fraction??undefined}></progress><span>{percent===null?'':`${percent}%`}</span></div>{/if}
 {#if running}<p class="current" title={current}>{current||'Preparing archive checks…'}</p>
 {:else if state==='password'}<div class="locked"><EncryptedBadge/><span>Enter the archive password.</span></div>
 {:else if state==='failed'}<div class="failure"><strong>Archive data could not be verified</strong><span>See Details for the reported error.</span></div>
 {:else if state==='passed'}<p class="support-note">{tar?'TAR has no per-file content checksums.':files?'No corruption detected within these checks.':'The archive contains no files.'}</p>
 {:else if state==='incomplete'&&encrypted}<p class="support-note">A wrong password can also cause decoding errors.</p>{/if}
 <details><summary>Details</summary><dl><div><dt>Files in archive</dt><dd>{files}</dd></div><div><dt>Format</dt><dd>{format}</dd></div>{#if receipt}<div><dt>Content read</dt><dd>{bytes(receipt.bytes_processed)}</dd></div>{/if}</dl>{#if failure}<pre>{failure}</pre>{/if}{#if receipt}<p>{receipt.message}</p>{/if}<p>Testing stops at the first error. A failed or interrupted test does not establish how many remaining files are intact.</p><p>Checks corruption, not malware. No files are extracted.</p></details>
 <footer><small>{state==='passed'?'Integrity check only':'No files extracted'}</small><div>{#if running}<button class="secondary" onclick={oncancel}>Cancel</button>{:else}{#if state==='password'||(state==='incomplete'&&encrypted)}<button class="secondary" onclick={onclose}>Close</button><button class="primary" onclick={onpassword}>Enter password…</button>{:else}{#if state!=='passed'}<button class="secondary" onclick={onretry}>Test again</button>{/if}<button class="primary" onclick={onclose}>Close</button>{/if}{/if}</div></footer>
</section>
<style>
 .test-panel{font-size:13px;color:var(--text);line-height:1.5}.archive{display:flex;align-items:center;gap:12px;padding:0 0 18px;border-bottom:1px solid var(--line)}.archive img{width:32px;height:32px}.archive strong{font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.result{display:flex;align-items:center;gap:14px;padding:22px 0 12px}.symbol{display:grid;place-items:center;flex-shrink:0;width:38px;height:38px;border-radius:50%;background:var(--muted);color:var(--surface);font-size:26px;font-weight:550;line-height:1}.result h3{font-size:18px;margin:0;font-weight:650;letter-spacing:-.3px}.result p{font-size:12px;color:var(--muted);margin:3px 0 0}[data-state=passed] .symbol{background:#248044;color:white}[data-state=failed] .symbol{background:#bb3f37;color:white}[data-state=running] .symbol{background:none;border:4px solid var(--line);border-top-color:var(--accent);border-right-color:var(--accent);animation:spin 1s linear infinite}.work{display:flex;align-items:center;gap:10px;margin:0 0 10px}.work progress{width:100%;height:8px;accent-color:var(--accent);border:0;border-radius:8px;overflow:hidden}.work progress::-webkit-progress-bar{background:var(--soft)}.work progress::-webkit-progress-value{background:var(--accent);border-radius:8px}[data-state=passed] progress{accent-color:#248044}[data-state=passed] progress::-webkit-progress-value{background:#248044}.work>span{font-size:12px;color:var(--muted);min-width:32px}.current{font-size:12px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-height:18px;margin:10px 0}.support-note{font-size:12px;color:var(--muted);margin:4px 0 16px}.failure{background:color-mix(in srgb,#bb3f37 9%,var(--surface));border:1px solid color-mix(in srgb,#bb3f37 30%,var(--surface));padding:10px 12px;border-radius:5px;margin:4px 0 16px;display:flex;flex-direction:column;gap:3px;font-size:12px}.failure>strong{color:var(--text)}.failure>span{color:var(--muted)}.locked{display:flex;align-items:center;gap:10px;margin:6px 0 18px;font-size:12px;color:var(--muted)}details{margin:20px 0}summary{cursor:pointer;font-weight:550}details p,details dl{font-size:12px;color:var(--muted)}dl>div{display:flex;justify-content:space-between;gap:20px;padding:5px 0}dd{margin:0}pre{font-size:12px;background:var(--soft);border-radius:5px;padding:12px;max-height:150px;overflow:auto}footer{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid var(--line);padding-top:16px}footer>small{font-size:11px;color:var(--muted)}footer>div{display:flex;gap:8px}button{font-size:13px;padding:8px 16px;border-radius:6px;min-height:36px;white-space:nowrap}.secondary{background:var(--surface);border:1px solid var(--line)}.secondary:hover{background:var(--soft)}.primary{min-width:88px}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){[data-state=running] .symbol{animation:none}}@media(max-width:440px){footer{align-items:flex-end;flex-wrap:wrap}.result h3{font-size:16px}}
</style>
